pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {BANK_SAFE} from "../src/BANK_SAFE.sol";

contract InvMutTest is Test {
    BANK_SAFE c;
    function setUp() public { c = new BANK_SAFE(); }
    function testRegression_property() public {
        c.Initialized();
        bool ok;
        try c.SetMinSum(10) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(!ok);
    }
}
